import express from "express";
import bodyParser from "body-parser";
import pg from "pg";

const app = express();
app.use(bodyParser.urlencoded({ extended: true }));
app.use(express.static("public"));

const db = new pg.Client({ user: "postgres", host: "localhost", database: "book_notes", password: "<your password>", port: 5432 });
db.connect();

app.get("/", async (req, res) => {
  const orderBy = req.query.orderBy || "date_read";
  const result = await db.query(`SELECT * FROM books ORDER BY ${orderBy} DESC`);
  res.render("index.ejs", { books: result.rows });
});

app.post("/new", async (req, res) => {
  const { title, author, rating, review, date_read, isbn } = req.body;
  await db.query(
    "INSERT INTO books (title, author, rating, review, date_read, isbn) VALUES ($1,$2,$3,$4,$5,$6)",
    [title, author, rating, review, date_read, isbn]
  );
  res.redirect("/");
});
// plus GET /new, GET+POST /books/:id/edit (UPDATE ... WHERE id=$7), POST /books/:id/delete (DELETE ... WHERE id=$1)

